INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-013', TRUE, '图书馆', '2026-10-29', '公告2026.10.29关于举办第十届“e博在线杯”校园阅读创作活动的通知', '图书资源', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "为深入贯彻落实党的二十大关于“深化全民阅读活动”的重要部署，积极响应“书香中国”与“教育强国”建设号", "quote": "为深入贯彻落实党的二十大关于“深化全民阅读活动”的重要部署，积极响应“书香中国”与“教育强国”建设号"}]'::jsonb, '图书资源：公告2026.10.29关于举办第十届“e博在线杯”校园阅读创作活动的通知', '[{"text": "为深入贯彻落实党的二十大关于“深化全民阅读活动”的重要部署，积极响应“书香中国”与“教育强国”建设号", "quote": "为深入贯彻落实党的二十大关于“深化全民阅读活动”的重要部署，积极响应“书香中国”与“教育强国”建设号"}]'::jsonb, '为深入贯彻落实党的二十大关于“深化全民阅读活动”的重要部署，积极响应“书香中国”与“教育强国”建设号召，充分发挥高校图书馆在文化育人中的阵地作用，安徽省高等学校图书情报工作委员会联合全省高校图书馆举办第十届“e博在线杯”校园阅读创作活动。 十载书香路，一卷天地宽。本届活动以“拾光阅典·智创青春”为主题，既是对“e博在线杯”过往阅读旅程的回望与致敬，更旨在引导青年学子在阅读中积淀人文底蕴，以经典智慧为根基，以创新思维为羽翼，拥抱数字化时代的新变革。AI浪潮奔涌，但阅读永远是思想最深的源泉。让科技与人文交织，让传统与未', 'https://lib.ahau.edu.cn/info/2401/55351.htm', '图书馆 · 新闻公告', 'lib', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at